import sys

def main():
    n, k, m = map(int, sys.stdin.read().split())
    C = [[0] * (n + 1) for _ in range(n + 1)]
    for i in range(n + 1):
        C[i][0] = 1 % m
        for j in range(1, i + 1):
            C[i][j] = (C[i - 1][j - 1] + (C[i - 1][j] if j <= i - 1 else 0)) % m
    p2 = [pow(2, i * (i - 1) // 2, m) for i in range(n + 1)]
    c = [0] * (n + 1)
    for i in range(1, n + 1):
        v = p2[i]
        for s in range(1, i):
            v -= C[i - 1][s - 1] * c[s] % m * p2[i - s]
        c[i] = v % m
    g = [[0] * (k + 1) for _ in range(n + 1)]
    g[0][0] = 1 % m
    for i in range(1, n + 1):
        for j in range(1, min(i, k) + 1):
            tot = 0
            for s in range(1, i - j + 2):
                tot += C[i - 1][s - 1] * c[s] % m * g[i - s][j - 1]
            g[i][j] = tot % m
    print(g[n][k] % m)

main()

