import sys
from fractions import Fraction
from math import comb, factorial

n, k, m = map(int, sys.stdin.read().split())
if n <= 6:
    edges = [(i, j) for i in range(n) for j in range(i + 1, n)]
    cnt = 0
    for mask in range(1 << len(edges)):
        par = list(range(n))
        def find(x):
            while par[x] != x:
                par[x] = par[par[x]]
                x = par[x]
            return x
        comps = n
        for idx, (a, b) in enumerate(edges):
            if mask >> idx & 1:
                ra, rb = find(a), find(b)
                if ra != rb:
                    par[ra] = rb
                    comps -= 1
        if comps == k:
            cnt += 1
    print(cnt % m)
else:
    # exponential formula with exact fractions: C(x) = log A(x), A(x) = sum 2^C(n,2) x^n / n!
    a = [Fraction(2 ** comb(i, 2), factorial(i)) for i in range(n + 1)]
    cc = [Fraction(0)] * (n + 1)
    for i in range(1, n + 1):
        cc[i] = a[i] - sum((j * cc[j] * a[i - j] for j in range(1, i)), Fraction(0)) / i
    cur = [Fraction(1)] + [Fraction(0)] * n
    for _ in range(k):
        new = [Fraction(0)] * (n + 1)
        for i in range(n + 1):
            if cur[i]:
                for j in range(1, n + 1 - i):
                    new[i + j] += cur[i] * cc[j]
        cur = new
    val = cur[n] * factorial(n) / factorial(k)
    assert val.denominator == 1
    print(int(val) % m)

